export { view } from "../../../base-ui/ui/separator";
export type {
  SeparatorOrientation,
  SeparatorStyle,
  ViewConfig,
} from "../../../base-ui/ui/separator";

export {
  shadcnHorizontalSeparatorClasses,
  shadcnSeparatorBaseClasses,
  shadcnSeparatorClassesByOrientation,
  shadcnVerticalSeparatorClasses,
} from "./view";

export {
  horizontalSeparatorClasses as shadcnHorizontalSeparatorClasses,
  separatorBaseClasses as shadcnSeparatorBaseClasses,
  separatorClassesByOrientation as shadcnSeparatorClassesByOrientation,
  verticalSeparatorClasses as shadcnVerticalSeparatorClasses,
} from "../../../base-ui/ui/separator/view";

import { describe, expect, test } from "vitest";

import * as Separator from "./index";

describe("shadcn Separator registry view", () => {
  test("reuses the Foldkit Separator view contract", () => {
    expect(Separator.view).toBeTypeOf("function");
    expect(
      Separator.shadcnSeparatorClassesByOrientation("vertical")
    ).toContain("w-px");
    expect(Separator.shadcnSeparatorBaseClasses).toContain("shrink-0");
  });
});
